select * from (values
  ('Range Rover Vogue', 'Luxury', 65000, 'https://images.unsplash.com/photo-1563720360172-67b8f3dce741?auto=format&fit=crop&w=1200&q=75', 5, 'Automatic', array['Chauffeur Available', 'Panoramic Roof', 'Air Suspension', 'Massage Seats', 'Meridian Audio'], true, 'The definitive luxury SUV. Whisper-quiet cabin, air suspension that glides over any road and a commanding presence for VIP movements, weddings and executive travel.', 'Land Rover', 2024, 'Petrol', 4, 4.9, 86, 4000),
  ('Rolls-Royce Wraith', 'Luxury', 150000, 'https://images.unsplash.com/photo-1631295868223-63265b40d9e4?auto=format&fit=crop&w=1200&q=75', 4, 'Automatic', array['Wedding Package', 'Starlight Headliner', 'Uniformed Chauffeur', 'Floral Décor', 'Red-Carpet Arrival'], true, 'Make an entrance nobody forgets. Our signature wedding and baraat car, delivered spotless with a uniformed chauffeur and optional floral décor.', 'Rolls-Royce', 2022, 'Petrol', 2, 5, 41, 6000),
  ('Mercedes-Benz GLE Coupé', 'Luxury', 55000, 'https://images.unsplash.com/photo-1590362891991-f776e747a588?auto=format&fit=crop&w=1200&q=75', 5, 'Automatic', array['AMG Line', 'Burmester Audio', '360° Camera', 'Ambient Lighting', 'Heated Seats'], true, 'Coupé styling with SUV comfort — sporty, refined and perfect for city cruising or corporate guests.', 'Mercedes-Benz', 2023, 'Petrol', 3, 4.8, 57, 4000),
  ('Porsche Panamera 4', 'Luxury', 85000, 'https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1200&q=75', 4, 'Automatic', array['Sport Chrono', 'Bose Audio', 'Adaptive Cruise', 'Leather Interior', 'Self-Drive Available'], false, 'A four-door sports car with grand-touring comfort. Ideal for photo shoots, events and special occasions.', 'Porsche', 2022, 'Petrol', 2, 4.9, 33, 5000),
  ('BMW 5 Series 530e', 'Luxury', 38000, 'https://images.unsplash.com/photo-1555215695-3004980ad54e?auto=format&fit=crop&w=1200&q=75', 5, 'Automatic', array['Executive Lounge', 'Head-Up Display', 'Harman Kardon', 'Wireless Charging', 'Chauffeur Available'], true, 'The executive’s choice — plug-in hybrid efficiency with a calm, premium cabin for business travel.', 'BMW', 2023, 'Hybrid', 3, 4.8, 74, 3500),
  ('Audi A6 Sedan', 'Luxury', 35000, 'https://images.unsplash.com/photo-1606664515524-ed2f786a0bd6?auto=format&fit=crop&w=1200&q=75', 5, 'Automatic', array['Virtual Cockpit', 'Matrix LED', 'Quattro AWD', 'Leather Seats', 'Apple CarPlay'], true, 'Understated luxury with Quattro all-wheel drive — composed on motorways and confident in the rain.', 'Audi', 2023, 'Petrol', 3, 4.7, 62, 3500),
  ('Toyota Camry Hybrid', 'Sedan', 16000, 'https://images.unsplash.com/photo-1621007947382-bb3c3994e3fb?auto=format&fit=crop&w=1200&q=75', 5, 'Automatic', array['Fuel Efficient', 'Climate Control', 'Lane Assist', 'Rear AC Vents', 'Apple CarPlay'], true, 'Spacious, smooth and remarkably efficient — our most-booked sedan for families and corporate clients.', 'Toyota', 2024, 'Hybrid', 3, 4.8, 128, 3000),
  ('Hyundai Elantra', 'Sedan', 9500, 'https://images.unsplash.com/photo-1619767886558-efdc259cde1a?auto=format&fit=crop&w=1200&q=75', 5, 'Automatic', array['Sunroof', 'Push Start', 'Reverse Camera', 'Cruise Control', 'Bluetooth'], true, 'Modern, well-equipped and great value for city errands, airport runs and intercity trips.', 'Hyundai', 2024, 'Petrol', 2, 4.6, 95, 2500),
  ('Tesla Model 3', 'Sedan', 22000, 'https://images.unsplash.com/photo-1606016159991-dfe4f2746ad5?auto=format&fit=crop&w=1200&q=75', 5, 'Automatic', array['Autopilot', 'Glass Roof', '15" Touchscreen', 'Silent Cabin', 'Home Charger Included'], true, 'All-electric, silent and quick. Comes fully charged with a portable charger for worry-free city use.', 'Tesla', 2023, 'Electric', 2, 4.7, 38, 3000),
  ('Volkswagen Polo', 'Sedan', 6500, 'https://images.unsplash.com/photo-1541899481282-d53bffe3c35d?auto=format&fit=crop&w=1200&q=75', 5, 'Manual', array['Economical', 'Easy Parking', 'AC', 'Bluetooth', 'Self-Drive'], true, 'Compact, nimble and economical — the smart pick for students, solo travellers and daily commutes.', 'Volkswagen', 2022, 'Petrol', 2, 4.5, 71, 2500),
  ('Honda CR-V', 'SUV', 18000, 'https://images.unsplash.com/photo-1519641471654-76ce0107ad1b?auto=format&fit=crop&w=1200&q=75', 5, 'Automatic', array['AWD', 'Honda Sensing', 'Large Boot', 'Rear AC', 'Roof Rails'], true, 'Comfortable family SUV with all-wheel drive and a huge boot — great for Murree and Nathia Gali trips.', 'Honda', 2023, 'Petrol', 4, 4.7, 66, 3000),
