  ('Audi Q5', 'SUV', 28000, 'https://images.unsplash.com/photo-1517524008697-84bbe3c3fd98?auto=format&fit=crop&w=1200&q=75', 5, 'Automatic', array['Quattro AWD', 'Panoramic Roof', 'Virtual Cockpit', 'Heated Seats', 'B&O Audio'], true, 'Premium SUV that is equally at home in Gulberg and on a snowy Malam Jabba road.', 'Audi', 2023, 'Petrol', 4, 4.8, 44, 3500),
  ('Ford Expedition', 'SUV', 32000, 'https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?auto=format&fit=crop&w=1200&q=75', 8, 'Automatic', array['8 Seater', '4x4', 'Captain Chairs', 'Tri-Zone AC', 'Tow Package'], true, 'Full-size 4x4 with room for eight and all their luggage — the ultimate family road-trip machine.', 'Ford', 2022, 'Petrol', 5, 4.7, 29, 3500),
