  ('Toyota Coaster Saloon', 'Van', 28000, 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=1200&q=75', 29, 'Manual', array['29 Seats', 'Driver Included', 'Reclining Seats', 'Roof AC', 'PA System'], true, 'Group tours, weddings and corporate retreats. Driver and fuel planning included on every booking.', 'Toyota', 2021, 'Diesel', 20, 4.6, 37, 0),
  ('Mercedes Sprinter Camper', 'Van', 30000, 'https://images.unsplash.com/photo-1513311068348-19c8fbdc0bb6?auto=format&fit=crop&w=1200&q=75', 6, 'Automatic', array['Sleeps 4', 'Kitchenette', 'Solar Power', 'Heater', 'Camping Gear'], true, 'Your hotel on wheels. Wake up beside a lake in Kalam — complete with kitchenette, bedding and camping kit.', 'Mercedes-Benz', 2021, 'Diesel', 8, 4.9, 18, 3500),
  ('Volkswagen Transporter', 'Van', 14000, 'https://images.unsplash.com/photo-1464219789935-c2d9d9aba644?auto=format&fit=crop&w=1200&q=75', 8, 'Manual', array['8 Seater', 'Sliding Doors', 'Rear AC', 'Large Luggage Space', 'Airport Transfers'], true, 'Practical people-mover for airport pick-ups, family events and medium-size groups.', 'Volkswagen', 2020, 'Diesel', 6, 4.5, 47, 3000)
